INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(120070, 'ruRU', '', 'Sound effect for troops', 24330),
(120114, 'ruRU', '', 'Я присоединюсь к своим павшим братьям и сёстрам. Прощай, Лирея.', 24330),
(120121, 'ruRU', '', 'Sound effect for troops', 24330),
(120122, 'ruRU', '', 'Sound effect for troops', 24330),
(120124, 'ruRU', '', 'Тебе следует вернуться к порталу. Верховный жрец и я позаботимся об остальном.', 24330),
(120132, 'ruRU', '', 'Ты монстр, Дарион!', 24330),
(120135, 'ruRU', '', 'Ну-ну, играйте дружно.', 24330),
(120136, 'ruRU', '', 'Не клади это в рот. Ты не знаешь, где оно побывало. Ох, а теперь не клади это В ЕГО рот!', 24330),
(120137, 'ruRU', '', 'Кто хочет поспать? ...Я хочу.', 24330),
(120138, 'ruRU', '', 'Это называется "вино". Мисс Лидди нужно оно, чтобы пережить день!', 24330),
(120139, 'ruRU', '', 'Обязательно ешь все свои питомцевы вкусняшки, если хочешь вырасти большим и достичь двадцать пятого уровня.', 24330),
(120140, 'ruRU', '', 'Если вы все будете хорошо себя вести сегодня, я почитаю вашу любимую историю, "Великое приключение Мерки".', 24330),
(120141, 'ruRU', '', 'Время для творчества! Погодите, кто съел весь клей? И блёстки? Давайте позвоним вашему владельцу, прежде чем это станет проблемой.', 24330),
(120146, 'ruRU', '', 'Свет истерзал его тело. Мы ничего не можем для него сделать.', 24330),
(120153, 'ruRU', '', 'Ты слишком поздно! Кросус станет твоим концом!', 24330),
(120181, 'ruRU', '', 'Теперь иди. Вернись, когда докажешь свою ценность.', 24330),
(120182, 'ruRU', '', 'Перед нами стоит трудное решение. Поможем ли мы жрецам в их битве против Балназара, или откажемся и подождём, чтобы сразиться с повелителем ужаса на своих условиях?', 24330),
(120188, 'ruRU', '', 'Я согласен с Аратором, Борос. Я почувствовал великую чистоту внутри этого создания.', 24330),
(120190, 'ruRU', '', 'Если позволите — Балназар не подозревает об объединённой силе. Конклав и Орден Серебряной Руки, сражающиеся вместе.', 24330),
(120191, 'ruRU', '', 'Значит, решено.', 24330),
(120196, 'ruRU', '', 'Я ждал тебя, $n.\n\nДелас сообщила совету о плане Балназара атаковать Храм Астрального Света. Вопрос в том, какую роль сыграют паладины в этой битве, если вообще сыграют? Мы рискуем многим, если решим помочь Конклаву.\n\nЭто решение нельзя принимать легкомысленно. Совету нужно обсудить, как действовать дальше.', 24330),
(120199, 'ruRU', '', 'Это магия Ночнорождённых... но она призвала нас.', 24330),
(120203, 'ruRU', '', 'Хороший выбор, только не называй меня "защитником". Никогда.', 24330),
(120213, 'ruRU', '', 'Пусть Элуна осветит твой путь, защитник.', 24330),
(120219, 'ruRU', '', 'Будь осторожен, шеф. Запределье — довольно опасное место, да и Шаттрат не намного лучше.', 24330),
(120221, 'ruRU', '', 'Следи за своей спиной и своими карманами.', 24330),
(120226, 'ruRU', '', 'На этот раз получилось быстро, но в будущем это займёт больше времени.', 24330),
(120229, 'ruRU', '', 'Прямо к северу от Ракетного пути! Приземлилась гигантская механическая глыба металла. Что это за чертовщина?', 24330),
(120244, 'ruRU', '', 'Кто ты, незнакомец? Ты не из Легиона.', 24330),
(120254, 'ruRU', '', 'Отлично сделано, $p! Теперь ты готов к бою.', 24330),
(120256, 'ruRU', '', 'Просто проследи, чтобы все были с ним по-настоящему милы. Иначе мы все можем проснуться мёртвыми завтра. Понимаешь, о чём я?', 24330),
(120261, 'ruRU', '', 'Удачи, шеф.', 24330),
(120265, 'ruRU', '', 'Ах, рука Короля-лича. Чем я могу тебе помочь?', 24330),
(120267, 'ruRU', '', 'Листва шепчет тревоги о демоническом огне и Кошмаре, но пока ты стоишь твёрдо, таковы и мы.\n\nЧем я могу помочь?', 24330),
(120269, 'ruRU', '', 'Тени шепчут множество секретов для тех, кто достаточно смел, чтобы слушать.', 24330),
(120271, 'ruRU', '', 'Будучи рыцарем смерти осквернения, ты повелеваешь силами болезни и смерти.', 24330),
(120274, 'ruRU', '', 'Ветра шепчут о твоих подвигах и о тех, что были прежде. Если я знаю правильные вопросы, которые нужно задать, мы можем узнать от них многое.', 24330),
(120277, 'ruRU', '', 'Будучи друидом равновесия, солнце, луна и звёзды — твои союзники, позволяющие обрушивать эти первородные силы на твоих врагов.', 24330),
(120286, 'ruRU', '', 'Ветра рассказывают мне о многом, недавнем и древнем. У этого твоего оружия есть история, которую стоит рассказать. Я начал записывать её в этот том.', 24330),
(120287, 'ruRU', '', 'Я продолжу добавлять в него, по мере того как узнаю больше.', 24330);
